import { Box } from '@mui/material'
import { memo, useLayoutEffect, useRef, useSyncExternalStore } from 'react'
import {
    diagramEditSessionService, type DiagramEditSessionService,
} from '../../services/diagrams/diagram_edit_session_service'
import { diagramGeometryService, type DiagramGeometryService } from '../../services/diagrams/diagram_geometry_service'
import { EditableDiagram } from './editable_diagram'
import type { DiagramSelectHandler } from './diagram_selection'

interface DiagramZoomViewportProps {
    geometry?: DiagramGeometryService
    onSelect?: DiagramSelectHandler
    session?: DiagramEditSessionService
}

const ignoreSelection: DiagramSelectHandler = () => undefined
const NewDiagram = memo(EditableDiagram)

function scaledCenterOffset(offset: number, viewportSize: number, previousScale: number, scale: number) {
    return (offset + viewportSize / 2) * scale / previousScale - viewportSize / 2
}

/** Scrollable New viewport whose visual scale leaves canonical diagram coordinates untouched. */
export function DiagramZoomViewport({
    geometry = diagramGeometryService,
    onSelect = ignoreSelection,
    session = diagramEditSessionService,
}: DiagramZoomViewportProps) {
    const scrollerRef = useRef<HTMLDivElement>(null)
    const scale = useSyncExternalStore(
        session.subscribeViewportScale,
        session.getViewportScaleSnapshot,
        session.getViewportScaleSnapshot,
    )
    const previousScaleRef = useRef(scale)

    useLayoutEffect(() => {
        const previousScale = previousScaleRef.current
        previousScaleRef.current = scale
        if (previousScale === scale) return

        const scroller = scrollerRef.current
        if (!scroller) return

        scroller.scrollLeft = scaledCenterOffset(scroller.scrollLeft, scroller.clientWidth, previousScale, scale)
        scroller.scrollTop = scaledCenterOffset(scroller.scrollTop, scroller.clientHeight, previousScale, scale)
    }, [scale])

    return (
        <Box
            aria-label="New diagram scroller"
            ref={scrollerRef}
            sx={{ flex: 1, minHeight: 0, overflow: 'auto', px: 2, pb: 2, pt: 1 }}
        >
            <Box data-testid="new-diagram-zoom-surface" sx={{ transformOrigin: 'top left', zoom: scale }}>
                <NewDiagram geometry={geometry} onSelect={onSelect} session={session} />
            </Box>
        </Box>
    )
}

import { Box, Paper, Typography } from '@mui/material'
import {
    memo, useCallback, useRef, useState, useSyncExternalStore,
    type KeyboardEvent as ReactKeyboardEvent,
    type PointerEvent as ReactPointerEvent,
} from 'react'
import {
    diagramEditSessionService, type DiagramEditSessionService,
} from '../../services/diagrams/diagram_edit_session_service'
import { diagramGeometryService, type DiagramGeometryService } from '../../services/diagrams/diagram_geometry_service'
import type { PositionedDiagramData } from '../../services/diagrams/diagram_layout'
import {
    diagramComparisonLayoutService, type DiagramComparisonLayoutService,
} from './diagram_comparison_layout_service'
import { DiagramRenderer } from './diagram_renderer'
import type { DiagramSelection } from './diagram_selection'
import { DiagramToolbox } from './diagram_toolbox'
import { DiagramZoomViewport } from './diagram_zoom_viewport'

const MINIMUM_PANE_HEIGHT = 160
const SEPARATOR_HEIGHT = 6
const KEYBOARD_RESIZE_STEP = 24
const MINIMUM_COMPARISON_HEIGHT = MINIMUM_PANE_HEIGHT * 2 + SEPARATOR_HEIGHT

interface DiagramComparisonProps {
    currentDiagram: PositionedDiagramData
    geometry?: DiagramGeometryService
    layoutService?: DiagramComparisonLayoutService
    onCurrentSelect: (anchorElement: HTMLElement, selection: DiagramSelection) => void
    session?: DiagramEditSessionService
}

const CurrentDiagram = memo(DiagramRenderer)

function availablePaneHeight(containerHeight: number) {
    return Math.max(containerHeight - SEPARATOR_HEIGHT, 0)
}

function clampTopPaneHeight(proposedHeight: number, availableHeight: number) {
    const minimumHeight = Math.min(MINIMUM_PANE_HEIGHT, availableHeight / 2)

    return Math.min(Math.max(proposedHeight, minimumHeight), availableHeight - minimumHeight)
}

function dividerRatioForHeight(proposedHeight: number, availableHeight: number) {
    if (availableHeight === 0) return 0.5

    return clampTopPaneHeight(proposedHeight, availableHeight) / availableHeight
}

/** Layout-only comparison root. Diagram changes remain inside New service-bound leaves. */
export function DiagramComparison({
    currentDiagram,
    geometry = diagramGeometryService,
    layoutService = diagramComparisonLayoutService,
    onCurrentSelect,
    session = diagramEditSessionService,
}: DiagramComparisonProps) {
    const containerRef = useRef<HTMLDivElement>(null)
    const [newViewportElement, setNewViewportElement] = useState<HTMLDivElement | null>(null)
    const activePointerIdRef = useRef<number | null>(null)
    const dividerRatio = useSyncExternalStore(
        layoutService.subscribeHorizontalDivider,
        layoutService.getHorizontalDividerSnapshot,
        layoutService.getHorizontalDividerSnapshot,
    )

    const setDividerFromClientY = useCallback((clientY: number) => {
        const container = containerRef.current
        if (!container) return

        const bounds = container.getBoundingClientRect()
        const availableHeight = availablePaneHeight(bounds.height)
        layoutService.setHorizontalDividerRatio(dividerRatioForHeight(clientY - bounds.top, availableHeight))
    }, [layoutService])

    const handlePointerDown = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
        event.preventDefault()
        activePointerIdRef.current = event.pointerId
        event.currentTarget.setPointerCapture?.(event.pointerId)
    }, [])

    const handlePointerMove = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
        if (activePointerIdRef.current !== event.pointerId) return

        setDividerFromClientY(event.clientY)
    }, [setDividerFromClientY])

    const stopPointerResize = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
        if (activePointerIdRef.current !== event.pointerId) return

        activePointerIdRef.current = null
        event.currentTarget.releasePointerCapture?.(event.pointerId)
    }, [])

    const handleSeparatorKeyDown = useCallback((event: ReactKeyboardEvent<HTMLDivElement>) => {
        const container = containerRef.current
        if (!container) return

        const availableHeight = availablePaneHeight(container.getBoundingClientRect().height)
        const currentHeight = dividerRatio * availableHeight
        const proposedHeightByKey: Record<string, number> = {
            ArrowDown: currentHeight + KEYBOARD_RESIZE_STEP,
            ArrowUp: currentHeight - KEYBOARD_RESIZE_STEP,
            End: availableHeight,
            Home: 0,
        }
        const proposedHeight = proposedHeightByKey[event.key]
        if (proposedHeight === undefined) return

        event.preventDefault()
        layoutService.setHorizontalDividerRatio(dividerRatioForHeight(proposedHeight, availableHeight))
    }, [dividerRatio, layoutService])

    return (
        <Box
            aria-label="Diagram comparison"
            ref={containerRef}
            sx={{
                display: 'grid',
                flex: 1,
                gridTemplateRows: `minmax(${MINIMUM_PANE_HEIGHT}px, ${dividerRatio}fr) ${SEPARATOR_HEIGHT}px minmax(${MINIMUM_PANE_HEIGHT}px, ${1 - dividerRatio}fr)`,
                minHeight: MINIMUM_COMPARISON_HEIGHT,
                overflow: 'hidden',
            }}
        >
            <Paper
                aria-label="Current"
                elevation={0}
                role="region"
                sx={{ border: '1px solid', borderColor: 'divider', borderRadius: 1.5, minHeight: 0, overflow: 'auto', p: 2 }}
            >
                <Typography color="custom.colHead" sx={{ mb: 1 }} variant="overline">Current</Typography>
                <CurrentDiagram data={currentDiagram} onSelect={onCurrentSelect} />
            </Paper>
            <Box
                aria-label="Resize Current and New diagrams"
                aria-orientation="horizontal"
                aria-valuemax={100}
                aria-valuemin={0}
                aria-valuenow={Math.round(dividerRatio * 100)}
                aria-valuetext={`Current pane ${Math.round(dividerRatio * 100)} percent`}
                onKeyDown={handleSeparatorKeyDown}
                onPointerCancel={stopPointerResize}
                onPointerDown={handlePointerDown}
                onPointerMove={handlePointerMove}
                onPointerUp={stopPointerResize}
                role="separator"
                sx={{
                    bgcolor: 'divider',
                    cursor: 'row-resize',
                    touchAction: 'none',
                    '&:focus-visible': { bgcolor: 'primary.main', outline: 'none' },
                    '&:hover': { bgcolor: 'primary.main' },
                }}
                tabIndex={0}
            />
            <Paper
                aria-label="New"
                elevation={0}
                ref={setNewViewportElement}
                role="region"
                sx={{ border: '1px solid', borderColor: 'divider', borderRadius: 1.5, display: 'flex', flexDirection: 'column', minHeight: 0, overflow: 'hidden', position: 'relative' }}
            >
                <Typography color="custom.colHead" sx={{ flexShrink: 0, px: 2, pt: 2 }} variant="overline">New</Typography>
                <DiagramZoomViewport geometry={geometry} session={session} />
                <DiagramToolbox boundaryElement={newViewportElement} session={session} />
            </Paper>
        </Box>
    )
}

import { act, cleanup, fireEvent, render, screen } from '@testing-library/react'
import { afterEach, describe, expect, it, vi } from 'vitest'
import type { DiagramData } from '../../services/diagrams/diagram_data'
import {
    DEFAULT_DIAGRAM_ZOOM,
    DIAGRAM_ZOOM_STEP,
    DiagramEditSessionService,
} from '../../services/diagrams/diagram_edit_session_service'
import { DiagramGeometryService } from '../../services/diagrams/diagram_geometry_service'
import type { DiagramRecord } from '../../services/diagrams/diagram_index'
import type { DiagramViewSourceSnapshot } from '../../services/diagrams/diagram_view_service'
import { DiagramZoomViewport } from './diagram_zoom_viewport'

const diagram: DiagramData = {
    edges: [],
    groups: [],
    meta: { description: 'Orders architecture', title: 'Overview', type: 'architecture', version: 1 },
    nodes: [{ id: 'orders', label: 'Orders', role: 'focal', x: 240, y: 120 }],
}
const record: DiagramRecord = { actionId: 'overview', id: 'diagram-1', label: 'Overview', path: 'design/diagrams/overview.json' }
const project = { branch: 'main', id: 'project', rootPath: 'C:/repo' }

class DiagramSourceStub extends EventTarget {
    private readonly source: DiagramViewSourceSnapshot = { diagram, record }

    getSourceSnapshot = () => this.source

    subscribeSource = (listener: () => void) => {
        this.addEventListener('sourceChanged', listener)

        return () => this.removeEventListener('sourceChanged', listener)
    }
}

function createHarness() {
    const session = new DiagramEditSessionService(new DiagramSourceStub())
    session.bindProject(project)
    session.start()

    return { geometry: new DiagramGeometryService(session), session }
}

afterEach(cleanup)

describe('DiagramZoomViewport', () => {
    it('scales only rendered New content and preserves visible center', () => {
        const { geometry, session } = createHarness()
        render(<DiagramZoomViewport geometry={geometry} session={session} />)
        const scroller = screen.getByLabelText('New diagram scroller')
        Object.defineProperties(scroller, {
            clientHeight: { configurable: true, value: 100 },
            clientWidth: { configurable: true, value: 200 },
        })
        scroller.scrollLeft = 100
        scroller.scrollTop = 50

        act(() => { session.zoomIn() })

        expect(screen.getByTestId('new-diagram-zoom-surface')).toHaveStyle({
            transformOrigin: 'top left',
            zoom: DEFAULT_DIAGRAM_ZOOM + DIAGRAM_ZOOM_STEP,
        })
        expect(scroller.scrollLeft).toBe(150)
        expect(scroller.scrollTop).toBe(75)
    })

    it('preserves visible center and canonical geometry while zooming out', () => {
        const { geometry, session } = createHarness()
        render(<DiagramZoomViewport geometry={geometry} session={session} />)
        const scroller = screen.getByLabelText('New diagram scroller')
        const editableDiagram = session.getEditableDiagram()
        Object.defineProperties(scroller, {
            clientHeight: { configurable: true, value: 100 },
            clientWidth: { configurable: true, value: 200 },
        })
        scroller.scrollLeft = 100
        scroller.scrollTop = 50

        act(() => { session.zoomOut() })

        expect(screen.getByTestId('new-diagram-zoom-surface')).toHaveStyle({
            transformOrigin: 'top left',
            zoom: DEFAULT_DIAGRAM_ZOOM - DIAGRAM_ZOOM_STEP,
        })
        expect(scroller.scrollLeft).toBe(50)
        expect(scroller.scrollTop).toBe(25)
        expect(session.getEditableDiagram()).toBe(editableDiagram)
        expect(session.getEditableDiagram()?.nodes[0]).toMatchObject({ x: 240, y: 120 })
    })

    it('keeps pointer selection on transformed diagram nodes accurate', () => {
        const { geometry, session } = createHarness()
        const onSelect = vi.fn()
        render(<DiagramZoomViewport geometry={geometry} onSelect={onSelect} session={session} />)

        act(() => { session.zoomOut() })
        fireEvent.click(screen.getByRole('button', { name: 'Orders' }), { clientX: 190, clientY: 120 })

        expect(onSelect).toHaveBeenCalledWith({ id: 'orders', label: 'Orders', left: 190, top: 120 })
    })
})

import { Box, ToggleButton, ToggleButtonGroup, Typography } from '@mui/material'
import { useCallback, useSyncExternalStore, type ReactNode, type SyntheticEvent } from 'react'
import {
    diagramComparisonLayoutService, type DiagramComparisonLayoutService, type DiagramComparisonMode,
} from './diagram_comparison_layout_service'

interface DiagramComparisonLayoutProps {
    horizontalComparison: ReactNode
    layoutService?: DiagramComparisonLayoutService
    tabbedComparison: ReactNode
    verticalComparison: ReactNode
}

/** Selects one stable comparison layout without observing diagram or edit-session state. */
export function DiagramComparisonLayout({
    horizontalComparison,
    layoutService = diagramComparisonLayoutService,
    tabbedComparison,
    verticalComparison,
}: DiagramComparisonLayoutProps) {
    const comparisonMode = useSyncExternalStore(
        layoutService.subscribeComparisonMode,
        layoutService.getComparisonModeSnapshot,
        layoutService.getComparisonModeSnapshot,
    )
    const handleModeChange = useCallback((_event: SyntheticEvent, mode: DiagramComparisonMode | null) => {
        if (!mode) return

        layoutService.setComparisonMode(mode)
    }, [layoutService])
    const comparisonByMode: Record<DiagramComparisonMode, ReactNode> = {
        horizontal: horizontalComparison,
        tabbed: tabbedComparison,
        vertical: verticalComparison,
    }

    return (
        <Box sx={{ display: 'flex', flex: 1, flexDirection: 'column', height: '100%', minHeight: 0, minWidth: 0, overflow: 'hidden' }}>
            <Box sx={{ alignItems: 'center', display: 'flex', flexShrink: 0, gap: 1, minWidth: 0, pb: 1 }}>
                <Typography color="text.secondary" sx={{ flexShrink: 0 }} variant="body2">Layout</Typography>
                <ToggleButtonGroup
                    aria-label="Diagram comparison layout"
                    exclusive
                    onChange={handleModeChange}
                    size="small"
                    sx={{
                        bgcolor: 'custom.track',
                        borderRadius: 1,
                        display: 'flex',
                        flex: 1,
                        minWidth: 0,
                        p: 0.375,
                        '& .MuiToggleButtonGroup-grouped': {
                            border: 0,
                            borderRadius: '6px !important',
                            flex: 1,
                            minWidth: 0,
                            px: 1,
                        },
                        '& .Mui-selected': { bgcolor: 'background.paper', color: 'primary.main' },
                    }}
                    value={comparisonMode}
                >
                    <ToggleButton value="vertical">Vertical</ToggleButton>
                    <ToggleButton value="horizontal">Horizontal</ToggleButton>
                    <ToggleButton value="tabbed">Tabbed</ToggleButton>
                </ToggleButtonGroup>
            </Box>
            <Box aria-label="Selected diagram comparison" sx={{ display: 'flex', flex: 1, minHeight: 0, minWidth: 0, overflow: 'auto' }}>
                {comparisonByMode[comparisonMode]}
            </Box>
        </Box>
    )
}

import { Box, Paper, Tab, Tabs, Typography } from '@mui/material'
import { memo, useCallback, useId, useSyncExternalStore, type SyntheticEvent } from 'react'
import {
    diagramEditSessionService, type DiagramEditSessionService,
} from '../../services/diagrams/diagram_edit_session_service'
import { diagramGeometryService, type DiagramGeometryService } from '../../services/diagrams/diagram_geometry_service'
import type { PositionedDiagramData } from '../../services/diagrams/diagram_layout'
import {
    diagramComparisonLayoutService, type DiagramComparisonLayoutService, type DiagramComparisonTab,
} from './diagram_comparison_layout_service'
import { DiagramRenderer } from './diagram_renderer'
import type { DiagramSelection } from './diagram_selection'
import { DiagramZoomViewport } from './diagram_zoom_viewport'

interface TabbedDiagramComparisonProps {
    currentDiagram: PositionedDiagramData
    geometry?: DiagramGeometryService
    layoutService?: DiagramComparisonLayoutService
    onCurrentSelect: (anchorElement: HTMLElement, selection: DiagramSelection) => void
    session?: DiagramEditSessionService
}

const CurrentDiagram = memo(DiagramRenderer)

/** Accessible tab layout that keeps both diagram surfaces mounted and their view state intact. */
export function TabbedDiagramComparison({
    currentDiagram,
    geometry = diagramGeometryService,
    layoutService = diagramComparisonLayoutService,
    onCurrentSelect,
    session = diagramEditSessionService,
}: TabbedDiagramComparisonProps) {
    const comparisonId = useId()
    const activeTab = useSyncExternalStore(
        layoutService.subscribeActiveTab,
        layoutService.getActiveTabSnapshot,
        layoutService.getActiveTabSnapshot,
    )
    const handleTabChange = useCallback((_event: SyntheticEvent, tab: DiagramComparisonTab) => {
        layoutService.setActiveTab(tab)
    }, [layoutService])
    const currentTabId = `${comparisonId}-current-tab`
    const currentPanelId = `${comparisonId}-current-panel`
    const newTabId = `${comparisonId}-new-tab`
    const newPanelId = `${comparisonId}-new-panel`

    return (
        <Box
            aria-label="Tabbed diagram comparison"
            sx={{ display: 'flex', flex: 1, flexDirection: 'column', minHeight: 0, minWidth: 0, overflow: 'hidden' }}
        >
            <Tabs
                aria-label="Diagram comparison"
                onChange={handleTabChange}
                sx={{
                    borderBottom: 1,
                    borderColor: 'divider',
                    flexShrink: 0,
                    minHeight: 40,
                    '& .MuiTabs-indicator': { height: 2 },
                    '& .MuiTab-root': { color: 'text.secondary', minHeight: 40, py: 0, textTransform: 'none' },
                    '& .MuiTab-root.Mui-selected': { color: 'primary.main' },
                }}
                value={activeTab}
            >
                <Tab aria-controls={currentPanelId} id={currentTabId} label="Current" value="current" />
                <Tab aria-controls={newPanelId} id={newTabId} label="New" value="new" />
            </Tabs>
            <Paper
                aria-labelledby={currentTabId}
                elevation={0}
                hidden={activeTab !== 'current'}
                id={currentPanelId}
                role="tabpanel"
                sx={{ border: '1px solid', borderColor: 'divider', borderRadius: 1.5, flex: 1, minHeight: 0, overflow: 'auto', p: 2 }}
            >
                <Typography color="custom.colHead" sx={{ mb: 1 }} variant="overline">Current</Typography>
                <CurrentDiagram data={currentDiagram} onSelect={onCurrentSelect} />
            </Paper>
            <Paper
                aria-labelledby={newTabId}
                elevation={0}
                hidden={activeTab !== 'new'}
                id={newPanelId}
                role="tabpanel"
                sx={{ border: '1px solid', borderColor: 'divider', borderRadius: 1.5, display: 'flex', flex: 1, flexDirection: 'column', minHeight: 0, overflow: 'hidden' }}
            >
                <Typography color="custom.colHead" sx={{ flexShrink: 0, px: 2, pt: 2 }} variant="overline">New</Typography>
                <DiagramZoomViewport geometry={geometry} session={session} />
            </Paper>
        </Box>
    )
}

import { useCallback, useSyncExternalStore } from 'react'
import type {
    DiagramConnectionPoint,
    DiagramEdge,
    DiagramEntityField,
    DiagramGroup,
    DiagramMeta,
    DiagramNode,
    DiagramSequenceFragment,
} from '../../services/diagrams/diagram_data'
import {
    diagramEditSessionService,
    type DiagramChangeField,
    type DiagramConnectionEndpoint,
    type DiagramEditSessionService,
} from '../../services/diagrams/diagram_edit_session_service'

function useDiagramSnapshot<Value>(
    subscribeScoped: (listener: () => void) => () => void,
    getSnapshot: () => Value,
    service: DiagramEditSessionService,
) {
    const subscribe = useCallback((listener: () => void) => {
        const unsubscribeScoped = subscribeScoped(listener)
        const unsubscribeSession = service.subscribeSession(listener)

        return () => {
            unsubscribeScoped()
            unsubscribeSession()
        }
    }, [service, subscribeScoped])

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

/** Subscribes one leaf to one editable metadata field. */
export function useEditableDiagramMetadataField<Field extends keyof DiagramMeta>(
    field: Field,
    service: DiagramEditSessionService = diagramEditSessionService,
) {
    const subscribe = useCallback(
        (listener: () => void) => service.subscribeMetadataField(field, listener),
        [field, service],
    )
    const getSnapshot = useCallback(() => service.getMetadataFieldSnapshot(field), [field, service])

    return useDiagramSnapshot(subscribe, getSnapshot, service)
}

/** Subscribes one leaf to one field of one editable node. */
export function useEditableDiagramNodeField<Field extends keyof DiagramNode>(
    nodeId: string,
    field: Field,
    service: DiagramEditSessionService = diagramEditSessionService,
) {
    const subscribe = useCallback(
        (listener: () => void) => service.subscribeNodeField(nodeId, field, listener),
        [field, nodeId, service],
    )
    const getSnapshot = useCallback(() => service.getNodeFieldSnapshot(nodeId, field), [field, nodeId, service])

    return useDiagramSnapshot(subscribe, getSnapshot, service)
}

/** Subscribes one leaf to one field of one editable edge. */
export function useEditableDiagramEdgeField<Field extends keyof DiagramEdge>(
    edgeId: string,
    field: Field,
    service: DiagramEditSessionService = diagramEditSessionService,
) {
    const subscribe = useCallback(
        (listener: () => void) => service.subscribeEdgeField(edgeId, field, listener),
        [edgeId, field, service],
    )
    const getSnapshot = useCallback(() => service.getEdgeFieldSnapshot(edgeId, field), [edgeId, field, service])

    return useDiagramSnapshot(subscribe, getSnapshot, service)
}

/** Subscribes one leaf to one field of one editable group. */
export function useEditableDiagramGroupField<Field extends keyof DiagramGroup>(
    groupId: string,
    field: Field,
    service: DiagramEditSessionService = diagramEditSessionService,
) {
    const subscribe = useCallback(
        (listener: () => void) => service.subscribeGroupField(groupId, field, listener),
        [field, groupId, service],
    )
    const getSnapshot = useCallback(() => service.getGroupFieldSnapshot(groupId, field), [field, groupId, service])

    return useDiagramSnapshot(subscribe, getSnapshot, service)
}

/** Subscribes one leaf to one field of one editable sequence fragment. */
export function useEditableDiagramFragmentField<Field extends keyof DiagramSequenceFragment>(
    fragmentId: string,
    field: Field,
    service: DiagramEditSessionService = diagramEditSessionService,
) {
    const subscribe = useCallback(
        (listener: () => void) => service.subscribeFragmentField(fragmentId, field, listener),
        [field, fragmentId, service],
    )
    const getSnapshot = useCallback(
        () => service.getFragmentFieldSnapshot(fragmentId, field),
        [field, fragmentId, service],
    )

    return useDiagramSnapshot(subscribe, getSnapshot, service)
}

/** Subscribes one leaf to one position-addressed entity field value. */
export function useEditableDiagramEntityField<Field extends keyof DiagramEntityField>(
    nodeId: string,
    fieldIndex: number,
    field: Field,
    service: DiagramEditSessionService = diagramEditSessionService,
) {
    const subscribe = useCallback(
        (listener: () => void) => service.subscribeEntityField(nodeId, fieldIndex, field, listener),
        [field, fieldIndex, nodeId, service],
    )
    const getSnapshot = useCallback(
        () => service.getEntityFieldValueSnapshot(nodeId, fieldIndex, field),
        [field, fieldIndex, nodeId, service],
    )

    return useDiagramSnapshot(subscribe, getSnapshot, service)
}

/** Subscribes one leaf to one edge connection-point field. */
export function useEditableDiagramConnectionPointField<Field extends keyof DiagramConnectionPoint>(
    edgeId: string,
    endpoint: DiagramConnectionEndpoint,
    field: Field,
    service: DiagramEditSessionService = diagramEditSessionService,
) {
    const subscribe = useCallback(
        (listener: () => void) => service.subscribeConnectionPointField(edgeId, endpoint, field, listener),
        [edgeId, endpoint, field, service],
    )
    const getSnapshot = useCallback(
        () => service.getConnectionPointFieldSnapshot(edgeId, endpoint, field),
        [edgeId, endpoint, field, service],
    )

    return useDiagramSnapshot(subscribe, getSnapshot, service)
}

function useEditableDiagramCollectionIds(
    objectKind: 'edge' | 'fragment' | 'group' | 'node',
    getSnapshot: () => readonly string[],
    service: DiagramEditSessionService,
) {
    const subscribe = useCallback(
        (listener: () => void) => service.subscribeCollectionMembership(objectKind, listener),
        [objectKind, service],
    )

    return useDiagramSnapshot(subscribe, getSnapshot, service)
}

export function useEditableDiagramNodeIds(service: DiagramEditSessionService = diagramEditSessionService) {
    return useEditableDiagramCollectionIds('node', service.getNodeIdsSnapshot, service)
}

export function useEditableDiagramEdgeIds(service: DiagramEditSessionService = diagramEditSessionService) {
    return useEditableDiagramCollectionIds('edge', service.getEdgeIdsSnapshot, service)
}

export function useEditableDiagramGroupIds(service: DiagramEditSessionService = diagramEditSessionService) {
    return useEditableDiagramCollectionIds('group', service.getGroupIdsSnapshot, service)
}

export function useEditableDiagramFragmentIds(service: DiagramEditSessionService = diagramEditSessionService) {
    return useEditableDiagramCollectionIds('fragment', service.getFragmentIdsSnapshot, service)
}

/** Subscribes a review collection only to semantic change membership and order. */
export function useEditableDiagramChangeIds(service: DiagramEditSessionService = diagramEditSessionService) {
    return useDiagramSnapshot(service.subscribeChangeIds, service.getChangeIdsSnapshot, service)
}

/** Subscribes one review leaf to one field of one semantic change. */
export function useEditableDiagramChangeField<Field extends DiagramChangeField>(
    changeId: string,
    field: Field,
    service: DiagramEditSessionService = diagramEditSessionService,
) {
    const subscribe = useCallback(
        (listener: () => void) => service.subscribeChangeField(changeId, field, listener),
        [changeId, field, service],
    )
    const getSnapshot = useCallback(
        () => service.getChangeFieldSnapshot(changeId, field),
        [changeId, field, service],
